int write_notice(const char *directory)
{
    int dirfd;
    int fd;
    int result = 0;
    const unsigned char *text = (const unsigned char *)NOTICE_TEXT;
    size_t remaining = strlen(NOTICE_TEXT);

    if (directory == NULL) {
        return -1;
    }

    dirfd = open(directory, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
    if (dirfd == -1) {
        return -1;
    }

    fd = openat(dirfd, NOTICE_FILENAME,
                O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0666);
    if (fd == -1) {
        close(dirfd);
        return -1;
    }

    while (remaining > 0) {
        ssize_t written = write(fd, text, remaining);

        if (written < 0) {
            if (errno == EINTR) {
                continue;
            }
            result = -1;
            break;
        }
        if (written == 0) {
            result = -1;
            break;
        }

        text += (size_t)written;
        remaining -= (size_t)written;
    }

    if (close(fd) == -1) {
        result = -1;
    }
    if (close(dirfd) == -1) {
        result = -1;
    }

    return result;
}

